"use client"

import * as React from "react"
import { cn } from "cn"

/**
 * Heatmap on a CSS grid (Recharts has no heatmap series). Cell intensity is a
 * color-mix of --chart-1 with the card ground; members: series (cells), axes
 * (row and column labels), legend (scale), tooltip (native title + label).
 */
function ChartHeatmap({
  rows,
  columns,
  values,
  label,
  axes = true,
  legend = true,
  tooltip = true,
  format = (v: number) => String(v),
  className,
}: {
  rows: string[]
  columns: string[]
  /** values[row][column] */
  values: number[][]
  label: string
  axes?: boolean
  legend?: boolean
  tooltip?: boolean
  format?: (value: number) => string
  className?: string
}) {
  const flat = values.flat()
  const min = Math.min(...flat)
  const max = Math.max(...flat)
  const pct = (v: number) => (max === min ? 100 : Math.round(((v - min) / (max - min)) * 85 + 15))

  return (
    <figure data-slot="chart" data-chart="heatmap" className={cn("flex w-full flex-col gap-3 text-xs", className)}>
      <div
        role="table"
        aria-label={label}
        className="grid gap-1"
        style={{ gridTemplateColumns: `${axes ? "auto " : ""}repeat(${columns.length}, minmax(0, 1fr))` }}
      >
        {axes && (
          <div role="row" className="contents">
            <span role="columnheader" />
            {columns.map((c) => (
              <span key={c} role="columnheader" className="truncate text-center text-muted-foreground">
                {c}
              </span>
            ))}
          </div>
        )}
        {rows.map((r, ri) => (
          <div key={r} role="row" className="contents">
            {axes && (
              <span role="rowheader" className="truncate pr-2 text-right text-muted-foreground">
                {r}
              </span>
            )}
            {columns.map((c, ci) => {
              const v = values[ri]?.[ci] ?? 0
              const text = `${r}, ${c}: ${format(v)}`
              return (
                <span
                  key={c}
                  role="cell"
                  aria-label={text}
                  title={tooltip ? text : undefined}
                  className="aspect-square min-h-4 rounded-sm"
                  style={{ background: `color-mix(in oklch, var(--chart-1) ${pct(v)}%, var(--muted))` }}
                />
              )
            })}
          </div>
        ))}
      </div>
      {legend && (
        <figcaption className="flex items-center gap-2 text-muted-foreground">
          <span>{format(min)}</span>
          <span
            aria-hidden="true"
            className="h-2 w-24 rounded-full"
            style={{ background: "linear-gradient(to right, color-mix(in oklch, var(--chart-1) 15%, var(--muted)), var(--chart-1))" }}
          />
          <span>{format(max)}</span>
        </figcaption>
      )}
    </figure>
  )
}

export { ChartHeatmap }
